// A sketch of 2PC's blocking window — DO NOT do this across services.
func twoPhaseCommit(coord *Coordinator, ps []Participant) error {
	// Phase 1: everyone locks rows and votes.
	for _, p := range ps {
		if err := p.Prepare(); err != nil { // holds locks until phase 2
			coord.AbortAll(ps) // release everyone's locks
			return err
		}
	}
	// If the coordinator dies HERE, every participant is stuck 'in doubt',
	// holding locks, unable to commit or roll back on its own.
	for _, p := range ps {
		p.Commit() // phase 2: finally release locks
	}
	return nil
}

// A saga is an ordered list of steps, each with a forward and a compensate.
type Step struct {
	Name       string
	Forward    func(ctx context.Context) error
	Compensate func(ctx context.Context) error
}

func runSaga(ctx context.Context, steps []Step) error {
	var done []Step // steps whose Forward succeeded
	for _, s := range steps {
		if err := s.Forward(ctx); err != nil {
			// Unwind in reverse: compensate everything already done.
			for i := len(done) - 1; i >= 0; i-- {
				_ = done[i].Compensate(ctx)
			}
			return fmt.Errorf("saga failed at %s: %w", s.Name, err)
		}
		done = append(done, s)
	}
	return nil
}

// Orchestration: one place owns the flow and decides next/compensate.
func (o *Orchestrator) PlaceOrder(ctx context.Context, id string) error {
	if err := o.payment.Charge(ctx, id); err != nil {
		return err // nothing to undo yet
	}
	if err := o.inventory.Reserve(ctx, id); err != nil {
		_ = o.payment.Refund(ctx, id) // compensate the charge
		return err
	}
	if err := o.shipping.Schedule(ctx, id); err != nil {
		_ = o.inventory.Release(ctx, id) // reverse order
		_ = o.payment.Refund(ctx, id)
		return err
	}
	return nil // choreography would instead emit events at each step
}

// Compensation is a NEW forward action that offsets a prior commit.
// Refund offsets Charge; it must be idempotent because it may be retried.
func (p *PaymentService) Refund(ctx context.Context, orderID string) error {
	// Idempotency: if we already refunded this order, do nothing.
	if p.alreadyRefunded(ctx, orderID) {
		return nil
	}
	// This does NOT delete the original charge row — it appends a refund,
	// leaving an auditable trail: charge(+$50) then refund(-$50).
	return p.recordLedgerEntry(ctx, orderID, -p.amountOf(ctx, orderID))
}

// One atomic transaction writes BOTH the business row and the event.
func CreateOrder(ctx context.Context, db *sql.DB, o Order) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() // no-op after a successful Commit

	if _, err := tx.ExecContext(ctx,
		`INSERT INTO orders(id, total) VALUES($1, $2)`, o.ID, o.Total); err != nil {
		return err
	}
	// Same tx: the event can NEVER be lost relative to the state change.
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO outbox(id, topic, payload) VALUES($1, 'order.created', $2)`,
		o.ID, o.JSON()); err != nil {
		return err
	}
	return tx.Commit() // both rows commit together, or neither does
}

// Consumer dedup: process each event id at most once, atomically.
func handleEvent(ctx context.Context, db *sql.DB, e Event) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// Claim the key; if it already exists this insert fails -> duplicate.
	_, err = tx.ExecContext(ctx,
		`INSERT INTO processed_events(id) VALUES($1)`, e.ID)
	if isUniqueViolation(err) {
		return nil // already handled: effectively-once, safe to ack
	}
	if err != nil {
		return err
	}
	applyEffect(tx, e)   // the real work, in the same tx as the dedup claim
	return tx.Commit()
}

