package main

import (
	"context"
	"errors"
	"fmt"
)

// Step: a local transaction plus the compensation that undoes it.
type Step struct {
	Name       string
	Forward    func(ctx context.Context) error
	Compensate func(ctx context.Context) error
}

// runSaga executes steps in order; on failure it compensates in reverse.
func runSaga(ctx context.Context, steps []Step) error {
	var done []Step
	for _, s := range steps {
		if err := s.Forward(ctx); err != nil {
			fmt.Printf("step %q failed: %v -> compensating\n", s.Name, err)
			for i := len(done) - 1; i >= 0; i-- {
				_ = done[i].Compensate(ctx) // best-effort, must be idempotent
				fmt.Printf("  compensated %q\n", done[i].Name)
			}
			return fmt.Errorf("saga aborted at %q: %w", s.Name, err)
		}
		done = append(done, s)
		fmt.Printf("step %q committed\n", s.Name)
	}
	return nil
}

func main() {
	steps := []Step{
		{Name: "charge",
			Forward:    func(ctx context.Context) error { return nil },
			Compensate: func(ctx context.Context) error { return nil }}, // refund
		{Name: "reserve",
			Forward:    func(ctx context.Context) error { return errors.New("out of stock") },
			Compensate: func(ctx context.Context) error { return nil }}, // release
	}
	if err := runSaga(context.Background(), steps); err != nil {
		fmt.Println("result:", err)
	}
}

package main

import "fmt"

// OutboxRow is an event staged in the same DB as the business state.
type OutboxRow struct {
	ID      int
	Topic   string
	Payload string
	Sent    bool
}

// store fakes a DB: orders plus an outbox table in one place.
type store struct {
	orders []string
	outbox []*OutboxRow
	nextID int
}

// CreateOrder writes the order AND its event atomically (same 'tx').
func (s *store) CreateOrder(id string) {
	// In real code these two writes share one sql.Tx and Commit together.
	s.orders = append(s.orders, id)
	s.nextID++
	s.outbox = append(s.outbox, &OutboxRow{
		ID: s.nextID, Topic: "order.created", Payload: id,
	})
}

// relay publishes unsent rows, marking each sent only AFTER a publish.
func (s *store) relay(publish func(OutboxRow) error) {
	for _, row := range s.outbox {
		if row.Sent {
			continue // already delivered
		}
		if err := publish(*row); err != nil {
			return // leave unsent; next relay pass retries (at-least-once)
		}
		row.Sent = true // marked sent only after confirmed publish
	}
}

func main() {
	s := &store{}
	s.CreateOrder("order-1")
	s.CreateOrder("order-2")
	s.relay(func(r OutboxRow) error {
		fmt.Printf("published %s -> %s\n", r.Topic, r.Payload)
		return nil
	})
	fmt.Printf("orders=%d outbox[0].sent=%v\n", len(s.orders), s.outbox[0].Sent)
}

