package main

import "fmt"

type Event struct {
	ID     string
	Amount int
}

// handle is idempotent: it claims the event id before applying the effect.
// In real code the seen-check and the effect share ONE DB transaction.
func handle(balance *int, seen map[string]bool, e Event) {
	if seen[e.ID] {
		fmt.Printf("duplicate %s ignored balance=%d\n", e.ID, *balance)
		return // effectively-once: safe to ack, no double effect
	}
	seen[e.ID] = true // claim the idempotency key
	*balance += e.Amount
	fmt.Printf("applied %s (+%d) balance=%d\n", e.ID, e.Amount, *balance)
}

func main() {
	balance := 0
	seen := map[string]bool{}
	handle(&balance, seen, Event{ID: "evt-1", Amount: 50})
	handle(&balance, seen, Event{ID: "evt-1", Amount: 50}) // duplicate delivery
	fmt.Println("final balance:", balance) // 50, not 100
}

