func TestCompensatesInReverse(t *testing.T) {
	var order []string
	mk := func(name string, fail bool) Step {
		return Step{
			Name: name,
			Forward: func(ctx context.Context) error {
				if fail {
					return errors.New("boom")
				}
				order = append(order, "F:"+name)
				return nil
			},
			Compensate: func(ctx context.Context) error {
				order = append(order, "C:"+name)
				return nil
			},
		}
	}
	steps := []Step{mk("a", false), mk("b", false), mk("c", true)}
	err := Run(context.Background(), steps)
	if err == nil {
		t.Fatal("expected error")
	}
	want := []string{"F:a", "F:b", "C:b", "C:a"} // c never committed; b then a compensated
	if len(order) != len(want) {
		t.Fatalf("got %v want %v", order, want)
	}
	for i := range want {
		if order[i] != want[i] {
			t.Fatalf("got %v want %v", order, want)
		}
	}
}

func TestAllSucceed(t *testing.T) {
	mk := func() Step {
		return Step{
			Forward:    func(ctx context.Context) error { return nil },
			Compensate: func(ctx context.Context) error { return nil },
		}
	}
	if err := Run(context.Background(), []Step{mk(), mk()}); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

