package solution

type OutboxRow struct {
	ID      int
	Topic   string
	Payload string
	Sent    bool
}

// Relay publishes unsent rows, marking each sent only after a confirmed publish.
// On a publish error it stops so the failed and remaining rows retry next pass.
func Relay(rows []*OutboxRow, publish func(OutboxRow) error) error {
	for _, row := range rows {
		if row.Sent {
			continue // already delivered; never publish twice
		}
		if err := publish(*row); err != nil {
			return err // leave unsent; next pass retries (at-least-once)
		}
		row.Sent = true // marked sent ONLY after a confirmed publish
	}
	return nil
}

