package solution

import (
	"errors"
	"testing"
)

func TestRelaySkipsSentAndStopsOnError(t *testing.T) {
	rows := []*OutboxRow{
		{ID: 1, Sent: true},           // already sent -> skip
		{ID: 2},                       // publish ok
		{ID: 3},                       // publish fails -> stop
		{ID: 4},                       // never reached this pass
	}
	var published []int
	err := Relay(rows, func(r OutboxRow) error {
		if r.ID == 3 {
			return errors.New("broker down")
		}
		published = append(published, r.ID)
		return nil
	})
	if err == nil {
		t.Fatal("expected error from failing publish")
	}
	if len(published) != 1 || published[0] != 2 {
		t.Fatalf("published=%v want [2]", published)
	}
	if !rows[1].Sent {
		t.Fatal("row 2 should be marked sent")
	}
	if rows[2].Sent || rows[3].Sent {
		t.Fatal("rows 3 and 4 must remain unsent for retry")
	}
}

func TestRelayAllSucceed(t *testing.T) {
	rows := []*OutboxRow{{ID: 1}, {ID: 2}}
	if err := Relay(rows, func(r OutboxRow) error { return nil }); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !rows[0].Sent || !rows[1].Sent {
		t.Fatal("all rows should be marked sent")
	}
}

