// Write the order AND the event in ONE transaction (transactional outbox).
func CreateOrder(ctx context.Context, db *sql.DB, o Order) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() // no-op after Commit

	if _, err := tx.ExecContext(ctx,
		`INSERT INTO orders(id, total) VALUES($1, $2)`, o.ID, o.Total); err != nil {
		return err
	}
	// Same tx: the event can never be lost relative to the state change.
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO outbox(id, topic, payload, sent) VALUES($1, 'order.created', $2, false)`,
		o.ID, o.JSON()); err != nil {
		return err
	}
	return tx.Commit() // order + event commit together, or neither does
}

// A separate background relay delivers unsent events at-least-once.
func relayLoop(ctx context.Context, db *sql.DB, broker Broker) {
	rows, _ := db.QueryContext(ctx,
		`SELECT id, topic, payload FROM outbox WHERE sent = false ORDER BY id`)
	defer rows.Close()
	for rows.Next() {
		var id, topic, payload string
		_ = rows.Scan(&id, &topic, &payload)
		if err := broker.Publish(ctx, topic, payload); err != nil {
			return // leave sent=false; next pass retries (idempotent consumers dedup)
		}
		_, _ = db.ExecContext(ctx, `UPDATE outbox SET sent = true WHERE id = $1`, id)
	}
}

type Event struct {
	ID     string
	Amount int
}

type IdempotencyStore interface {
	Seen(id string) (bool, error) // has this id already been processed?
	Mark(id string) error         // record id as processed
}

// Process applies effect at most once per event id (effectively-once).
func Process(store IdempotencyStore, e Event, effect func(Event) error) error {
	seen, err := store.Seen(e.ID)
	if err != nil {
		return err
	}
	if seen {
		return nil // duplicate delivery: already applied, safe to ack
	}
	if err := effect(e); err != nil {
		return err // effect failed: DON'T mark, so a retry can re-run it
	}
	return store.Mark(e.ID) // record only AFTER the effect succeeded
}
